def solve(g):
    g=np.array(g); h,w=g.shape
    cnt=Counter(g.flatten()); keep={c for c,n in cnt.items() if n>=cnt.most_common(2)[1][0]}
    # find connected same-color comps of kept colors -> bbox rects; also merge overlapping boxes
