# For each grid, collect all non-bg cells with their distance to nearest kept-rect cell.
def comps_of(g,bg,minsize):
    H,W=g.shape; seen=np.zeros_like(g,bool); res=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]!=bg and not seen[i,j]:
                st=[(i,j)]; seen[i,j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<H and 0<=b<W and not seen[a,b] and g[a,b]==g[i,j]:
                                seen[a,b]=True; st.append((a,b))
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                r1=max(p[0] for p in cells); c1=max(p[1] for p in cells)
                res.append({'cells':cells,'col':int(g[i,j]),'bbox':(r0,c0,r1,c1),'size':len(cells)})
    return [c_ for c_ in res if c_['size']>=minsize]
