                near.append((best,Rk['col'],Rk['bbox']))
            near.sort(key=lambda t:t[0])
            out.append(((i,j,int(g[i,j])), int(go[i,j]), 'in',ins,'ed',edge,'near',near[:2]))
    return bg,R,out
