                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                r1=max(p[0] for p in cells); c1=max(p[1] for p in cells)
                comps.append({'cells':set(cells),'col':int(g[cells[0][0]][cells[0][1]]),
                              'r0':r0,'c0':c0,'r1':r1,'c1':c1})
    out=[[int(g[i][j]) for j in range(W)] for i in range(H)]
    big=[cc for cc in comps if cc['n']>1]
    for cc in big:
        col=cc['col']
        for x in range(cc['r0'],cc['r1']+1):
            for y in range(cc['c0'],cc['c1']+1):
                out[x][y]=col
    for cc in comps:
        if cc['n']==1:
            x,y=list(cc['cells'])[0]; out[x][y]=bg
    return out
