import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def comps(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=set()
                while st:
                    x,y=st.pop(); cells.add((x,y))
                    for dx in (-1,0,1):
                        for dy in (-1,0,1):
                            t=(x+dx,y+dy)
                            if 0<=t[0]<H and 0<=t[1]<W and not seen[t[0]][t[1]] and g[t[0]][t[1]]==g[x][y]:
                                seen[t[0]][t[1]]=True; st.append(t)
                r0=min(p[0] for p in cells); c0=min(p[1] for p in cells)
                r1=max(p[0] for p in cells); c1=max(p[1] for p in cells)
                col=g[i][j]
                out.append({'r0':r0,'c0':c0,'r1':r1,'c1':c1,'col':col,'cells':set(cells)})
    return out

def f(g):
    H,W=len(g),len(g[0]); bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    C=comps(g,bg)
    regs=[]
    for cc in C:
        n=len(cc['cells']); a=(cc['r1']-cc['r0']+1)*(cc['c1']-cc['c0']+1)
        if a==0: continue
        dens=n/a
        # keep dense comps plus perfect small ones
        ok = (dens>=0.75 and n>=4) or (a==n and n>=2) or (n>=6)
        if ok: regs.append(cc)
    out=[[bg]*W for _ in range(H)]
    for cc in regs:
        col=cc['col']
        for x in range(cc['r0'],cc['r1']+1):
            for y in range(cc['c0'],cc['c1']+1):
                out[x][y]=col
    # erase stray non-bg cells outside regions' bboxes / wrong color inside
    def keep_cell(x,y,col_in):
        for cc in regs:
            if cc['r0']<=x<=cc['r1'] and cc['c0']<=y<=cc['c1']: return True
        return False
    res=[[out[r][c] for c in range(W)] for r in range(H)]
    for i,row in enumerate(out):
        for j,v in enumerate(row):
            if v!=bg and not keep_cell(i,j,v):
                res[i][j]=bg
    return res

