def f(g):
    H,W=len(g),len(g[0]); bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    C=comps(g,bg)
    pos={(x,y):k for k,cc in enumerate(C) for x,y in cc['cells']}
    done=set(); regs=[]
    for start in range(len(C)):
        if start in done: continue
        group={start}; stack=[start]; seed=start
        while stack:
            q=stack.pop(); cc=C[q]
            for nx in range(cc['r0']-1,cc['r1']+2):
                for ny in range(cc['c0']-1,cc['c1']+2):
                    k2=pos.get((nx,ny))
                    if k2 is None or k2 in group: continue
                    if C[k2]['col']==C[q]['col'] and touches(C[q],C[k2]):
                        group.add(k2); stack.append(k2); seed=k2
        for kk in group: done.add(kk)
        allcells=set()
        for kk in group: allcells|=C[kk]['cells']
        rs=min(p[0] for p in allcells); r1=max(p[0] for p in allcells)
        cs0=min(p[1] for p in allcells); c1=max(p[1] for p in allcells)
        n=sum(len(C[kk]['cells']) for kk in group)
        a=(r1-rs+1)*(c1-cs0+1)
        ok = n>=6 or (a==n and n>=2) or (n/a>=0.6 and n>=4)
        if ok:
            regs.append({'box':(rs,r1,cs0,c1),'n':n,'col':C[seed]['col']})
    seq=sorted(regs,key=lambda v:-v['n'])
    out=[[bg]*W for _ in range(H)]
    for region in seq:
        (rs_,r1_,cs0_,c1_),n,col=region['box'],region['n'],region['col']
        for x in range(rs_,r1_+1):
            for y in range(cs0_,c1_+1):
                out[x][y]=col
    def owners(x,y):
        own=[]
        for reg in regs:
            (rs_,r1_,cs0_,c1_),n,col=reg['box'],reg['n'],reg['col']
            if rs_<=x<=r1_ and cs0_<=y<=c1_: own.append(col)
        return own
    res=[row[:] for row in out]
    for r in range(H):
        for c in range(W):
            cols=owners(r,c)
            if len(cols)==1 and g[r][c]!=cols[0]:
                res[r][c]=cols[0]
    return res

